def trans(s, refl, rot):
 z=[]
 for r,c in s:
  if refl: c=-c
  for _ in range(rot): r,c=c,-r
  z.append((r,c))
 mr=min(r for r,c in z); mc=min(c for r,c in z)
 return {(r-mr,c-mc) for r,c in z}
def place(seed,templ, desired=None):
 # enumerate all transformations and placements in target that contain seed, choose centered target bbox close to seed bbox
 sr0=min(r for r,c in seed); sc0=min(c for r,c in seed); sr1=max(r for r,c in seed); sc1=max(c for r,c in seed)
 best=[]
 for refl in (0,1):
  for rot in range(4):
   t=trans(templ,refl,rot)
   tr0=min(r for r,c in t); tc0=min(c for r,c in t); tr1=max(r for r,c in t); tc1=max(c for r,c in t)
   for dr in range(-tr1+sr0, sr1-tr0+1):
    for dc in range(-tc1+sc0, sc1-tc0+1):
     moved={(r+dr,c+dc) for r,c in seed}
     if moved <= t:
      # t shifts into grid by offset anchor; derive template target absolute coordinates from seed alignment
      # shift template absolute = -dr relative to seed coordinates
      # prefer template bbox center close to seed bbox center, plus matching shape bbox ratio
      boxcenter_seed=((sr0+sr1)/2,(sc0+sc1)/2)
      boxcenter_t=((tr0-dr+tr1-dr)/2,(tc0-dc+tc1-dc)/2)
      score=abs(boxcenter_t[0]-boxcenter_seed[0])+abs(boxcenter_t[1]-boxcenter_seed[1])
      best.append((score,refl,rot,dr,dc,t))
 return sorted(best,key=lambda x:(x[0],x[1],x[2],x[3],x[4]))
